CREATE OR REPLACE FUNCTION account_private.check_assignee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists(select 1 from account_private.access where user_id=new.perfil_id and estado='aprobada') then
    raise exception 'Solo puedes asignar empleados con acceso aprobado' using errcode='23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION account_private.filter_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.tipo in ('cuenta_aprobada','cuenta_rechazada') or exists (
    select 1 from account_private.access where user_id=new.perfil_id and estado='aprobada'
  ) then return new; end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION account_private.new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_username text := btrim(coalesce(new.raw_user_meta_data->>'nombre_usuario', ''));
  v_name text := btrim(coalesce(new.raw_user_meta_data->>'nombre_completo', ''));
  v_phone text := btrim(coalesce(new.raw_user_meta_data->>'telefono', ''));
  v_digits text := regexp_replace(v_phone, '[^0-9]', '', 'g');
  v_cargo text := account_private.normalizar_cargo(new.raw_user_meta_data->>'cargo');
begin
  if char_length(v_username) not between 3 and 30
     or v_username !~ '^[A-Za-z0-9][A-Za-z0-9._-]*$' then
    raise exception 'El nombre de usuario no es valido' using errcode = '22023';
  end if;
  if char_length(v_name) not between 2 and 80
     or v_name ~ '[0-9]' or v_name ~ '[[:cntrl:]]' then
    raise exception 'El nombre completo no es valido' using errcode = '22023';
  end if;
  if char_length(v_digits) not between 10 and 15
     or v_phone !~ '^[0-9+() -]+$' then
    raise exception 'El telefono no es valido' using errcode = '22023';
  end if;
  if v_cargo is null then
    raise exception 'El cargo no pertenece al catalogo de la empresa' using errcode = '22023';
  end if;

  insert into public.perfiles(id, nombre_completo, rol, telefono, cargo)
  values(new.id, v_name, 'empleado', v_phone, v_cargo)
  on conflict(id) do update set
    nombre_completo = coalesce(public.perfiles.nombre_completo, excluded.nombre_completo),
    telefono = coalesce(public.perfiles.telefono, excluded.telefono),
    cargo = coalesce(public.perfiles.cargo, excluded.cargo),
    rol = case when public.perfiles.rol = 'tecnico' then 'empleado' else public.perfiles.rol end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION account_private.protect_profile_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.role() in ('authenticated', 'anon')
     and new.nombre_completo is distinct from old.nombre_completo then
    raise exception 'El nombre completo no se puede modificar' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_assignments_page(p_offset integer DEFAULT 0, p_limit integer DEFAULT 50, p_estado text DEFAULT 'pendientes'::text, p_busqueda text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  page_size integer := least(100, greatest(1, coalesce(p_limit, 50)));
  page_offset integer := greatest(0, coalesce(p_offset, 0));
  search_text text := lower(trim(coalesce(p_busqueda, '')));
  result jsonb;
begin
  if auth.uid() is null or not coalesce(public.es_admin(), false) then
    raise exception 'Solo administradores' using errcode = '42501';
  end if;
  if p_estado is null or p_estado not in ('todas', 'pendientes', 'vencidas', 'completadas') then
    raise exception 'Filtro de estado no valido' using errcode = '22023';
  end if;
  if length(search_text) > 100 then
    raise exception 'La busqueda excede 100 caracteres' using errcode = '22023';
  end if;
  with candidates as materialized (
    select a.* from public.asignaciones a
    where (
      p_estado = 'todas'
        or (p_estado = 'completadas' and a.estado = 'completada')
        or (p_estado = 'vencidas' and a.estado <> 'completada'
          and (a.estado = 'vencida' or a.fecha_limite <= now()))
        or (p_estado = 'pendientes' and a.estado in ('pendiente', 'en_curso')
          and (a.fecha_limite is null or a.fecha_limite > now()))
    ) and (
      search_text = ''
      or strpos(lower(a.titulo), search_text) > 0
      or strpos(lower(coalesce(a.ubicacion, '')), search_text) > 0
      or exists (
        select 1 from public.asignacion_equipo search_team
        join public.perfiles search_profile on search_profile.id = search_team.perfil_id
        where search_team.asignacion_id = a.id
          and strpos(lower(coalesce(search_profile.nombre_completo, '')), search_text) > 0
      )
    )
    order by a.fecha_creacion desc, a.id desc
    limit page_size + 1 offset page_offset
  ), page as (
    select * from candidates order by fecha_creacion desc, id desc limit page_size
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(
      to_jsonb(p) || jsonb_build_object(
        'hitos_itinerario', coalesce((
          select jsonb_agg(to_jsonb(h) order by h.orden)
          from public.hitos_itinerario h where h.asignacion_id = p.id
        ), '[]'::jsonb),
        'asignacion_equipo', coalesce((
          select jsonb_agg(jsonb_build_object('perfiles', to_jsonb(profile)))
          from public.asignacion_equipo team
          join public.perfiles profile on profile.id = team.perfil_id
          where team.asignacion_id = p.id
        ), '[]'::jsonb)
      ) order by p.fecha_creacion desc, p.id desc)
      from page p), '[]'::jsonb),
    'has_more', (select count(*) > page_size from candidates),
    'next_offset', case when (select count(*) > page_size from candidates)
      then page_offset + page_size else null end
  ) into result;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_assignment(p_asignacion jsonb, p_empleados uuid[], p_hitos jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare aid uuid; team uuid[]; supervisors jsonb:=coalesce(p_asignacion->'supervisores','[]'::jsonb);
begin
  team:=milestone_private.validate_members(p_hitos,supervisors);
  aid:=milestone_private.create_legacy(p_asignacion,team,p_hitos);
  perform milestone_private.save_members(aid,p_hitos,supervisors);
  perform sla_private.advance(aid);
  return aid;
end $function$

CREATE OR REPLACE FUNCTION public.admin_delete_assignment(p_asignacion_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not public.account_is_approved() or not public.es_admin() then
    raise exception 'Solo administradores pueden eliminar asignaciones' using errcode='42501'; end if;
  perform 1 from public.asignaciones where id=p_asignacion_id for update;
  if not found then raise exception 'La asignacion ya no existe'; end if;
  perform set_config('soundisco.deleting_assignment',p_asignacion_id::text,true);
  delete from public.checklist_equipos where asignacion_id=p_asignacion_id;
  update public.notificaciones_app set asignacion_relacionada_id=null where asignacion_relacionada_id=p_asignacion_id;
  delete from public.hitos_itinerario where asignacion_id=p_asignacion_id;
  delete from public.asignacion_equipo where asignacion_id=p_asignacion_id;
  delete from public.asignaciones where id=p_asignacion_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_review_account(p_user_id uuid, p_estado text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous text;
begin
  if not public.es_admin() then raise exception 'Solo administradores pueden revisar cuentas' using errcode = '42501'; end if;
  if p_estado is null or p_estado not in ('aprobada','rechazada') then raise exception 'Estado invalido'; end if;
  select estado into previous from account_private.access where user_id=p_user_id for update;
  if previous is null then raise exception 'La cuenta ya no existe'; end if;
  if previous = p_estado then return; end if;
  if previous = 'aprobada' then raise exception 'Este flujo solo revisa solicitudes pendientes o rechazadas'; end if;
  update account_private.access set estado=p_estado,reviewed_at=now(),reviewed_by=auth.uid() where user_id=p_user_id;
  perform notification_private.emit(p_user_id,
    case when p_estado='aprobada' then 'cuenta_aprobada' else 'cuenta_rechazada' end,
    case when p_estado='aprobada' then 'Cuenta verificada' else 'Solicitud revisada' end,
    case when p_estado='aprobada' then 'Tus credenciales han sido aprobadas. Ya puedes acceder al sistema'
      else 'Tu solicitud no fue aprobada. Contacta con administracion.' end,
    'perfil',p_user_id,p_estado,'acceso:'||p_user_id::text||':'||gen_random_uuid()::text);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_suspend_account(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(public.account_is_approved(),false) or not public.es_admin() then
    raise exception 'Solo administradores pueden suspender accesos' using errcode='42501'; end if;
  if p_user_id=auth.uid() or exists(select 1 from public.perfiles where id=p_user_id and rol='admin') then
    raise exception 'No puedes suspender una cuenta administradora desde este panel' using errcode='42501'; end if;
  update account_private.access set estado='rechazada',reviewed_at=now(),reviewed_by=auth.uid()
    where user_id=p_user_id;
  if not found then raise exception 'La cuenta ya no existe' using errcode='P0002'; end if;
  delete from notification_private.devices where perfil_id=p_user_id;
  if to_regclass('android_push_private.devices') is not null then
    execute 'delete from android_push_private.devices where perfil_id=$1' using p_user_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_assignment(p_asignacion_id uuid, p_asignacion jsonb, p_empleados uuid[], p_hitos jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare team uuid[]; supervisors jsonb:=coalesce(p_asignacion->'supervisores','[]'::jsonb);
begin
  team:=milestone_private.validate_members(p_hitos,supervisors);
  perform 1 from public.asignaciones where id=p_asignacion_id for update;
  perform milestone_private.update_legacy(p_asignacion_id,p_asignacion,team,p_hitos);
  perform milestone_private.save_members(p_asignacion_id,p_hitos,supervisors);
  perform sla_private.advance(p_asignacion_id);
end $function$

CREATE OR REPLACE FUNCTION public.check_account_access()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare path text := trim(both '/' from coalesce(current_setting('request.path',true),''));
begin
    if auth.role() = 'authenticated' and not public.account_is_approved() then
        if path in ('rpc/my_account_access','rpc/delete_my_account',
            'rpc/register_push_device','rpc/unregister_push_device',
            'rpc/register_android_push_device','rpc/unregister_android_push_device') then return; end if;
        if path = 'perfiles' and current_setting('request.method',true) in ('GET','HEAD') then return; end if;
        raise exception 'Tu cuenta no tiene acceso aprobado' using errcode = '42501';
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_in_milestone(p_hito_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h public.hitos_itinerario%rowtype; aid uuid; checked timestamptz:=statement_timestamp();
  evaluation text; recipient uuid; actor_name text; confirmation_id uuid;
begin
  if auth.uid() is null or not coalesce(public.account_is_approved(),false) then
    raise exception 'Acceso no aprobado' using errcode='42501'; end if;
  select asignacion_id into aid from public.hitos_itinerario where id=p_hito_id;
  perform 1 from public.asignaciones where id=aid for update;
  select * into h from public.hitos_itinerario where id=p_hito_id;
  if not found then raise exception 'El hito ya no existe'; end if;
  if not exists(select 1 from public.hitos_colaboradores where hito_id=h.id and usuario_id=auth.uid()) then
    raise exception 'No estás asignado a este hito' using errcode='42501'; end if;
  if exists(select 1 from public.hitos_colaboradores where hito_id=h.id and usuario_id=auth.uid() and confirmado_at is not null) then return; end if;
  if h.fecha_programada is null then raise exception 'Falta la fecha límite del hito'; end if;
  if exists(select 1 from public.hitos_itinerario m join public.hitos_colaboradores c on c.hito_id=m.id
    where m.asignacion_id=aid and m.orden<h.orden and c.usuario_id=auth.uid() and c.confirmado_at is null) then
    raise exception 'Confirma primero tu hito anterior' using errcode='23514'; end if;
  evaluation:=milestone_private.confirmation_evaluation(checked,h.fecha_programada);
  update public.hitos_colaboradores set confirmado_at=checked,hora_programada=h.fecha_programada,estado=evaluation
    where hito_id=h.id and usuario_id=auth.uid();
  insert into public.confirmaciones_hitos(asignacion_id,hito_id,usuario_id,created_at,hora_programada,evaluacion)
    values(aid,h.id,auth.uid(),checked,h.fecha_programada,evaluation) returning id into confirmation_id;
  select coalesce(nombre_completo,'Un colaborador') into actor_name from public.perfiles where id=auth.uid();
  for recipient in
    select id from public.perfiles where rol='admin'
    union select usuario_id from public.asignacion_supervisores where asignacion_id=aid
  loop
    perform notification_private.emit(recipient,'hito_completado','Confirmación de Hito',
      actor_name||' confirmó '||h.descripcion,'asignacion',aid,null,'checkin:'||confirmation_id::text);
  end loop;
  perform set_config('soundisco.individual_checkin','true',true);
  perform sla_private.advance(aid);
  if exists(select 1 from public.asignaciones where id=aid and estado='completada') then
    for recipient in
      select id from public.perfiles where rol='admin'
      union select usuario_id from public.asignacion_supervisores where asignacion_id=aid
    loop
      perform notification_private.emit(recipient,'asignacion_completada','Asignación completada',
        'El evento ha sido completado al 100%','asignacion',aid,'completada','checkin-complete:'||confirmation_id::text);
    end loop;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_my_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid := auth.uid(); full_name text; user_email text;
begin
  if uid is null then raise exception 'Sesion requerida' using errcode = '42501'; end if;
  select nombre_completo into full_name from public.perfiles where id=uid for update;
  select email into user_email from auth.users where id=uid;
  delete from notification_private.devices where perfil_id=uid;
  delete from public.asignacion_equipo where perfil_id=uid;
  update public.comunicados set leido_por=array_remove(leido_por,uid) where uid=any(leido_por);
  delete from public.notificaciones_app where perfil_id=uid or (destino_tipo='perfil' and destino_id=uid)
    or (nullif(full_name,'') is not null and destino_tipo='asignacion'
      and left(mensaje,length(full_name)+1)=full_name||' ')
    or (nullif(user_email,'') is not null and position(user_email in mensaje)>0);
  update notification_private.assignment_events set actor=null where actor=uid;
  delete from public.perfiles where id=uid;
  delete from auth.users where id=uid;
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_android_notification_push(p_job uuid, p_lease uuid, p_success boolean, p_error text, p_invalid boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j android_push_private.outbox%rowtype;
begin
    select * into j from android_push_private.outbox where id = p_job and lease_id = p_lease and sent_at is null for update;
    if not found then return; end if;
    if p_invalid then
        delete from android_push_private.devices
        where installation = j.installation and perfil_id = j.recipient and token = j.leased_token;
    end if;
    update android_push_private.outbox set
        sent_at = case when p_success then now() else null end,
        last_error = case when p_success then null else left(p_error, 120) end,
        lease_id = null, leased_until = null,
        next_attempt = now() + make_interval(secs => least(3600, (power(2, j.attempts) * 15)::integer))
    where id = j.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_android_push(p_job uuid, p_lease uuid, p_success boolean, p_error text, p_invalid boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j android_push_private.outbox%rowtype;
begin
  select * into j from android_push_private.outbox
    where id=p_job and lease_id=p_lease and sent_at is null for update;
  if not found then return; end if;
  if p_invalid then
    delete from android_push_private.devices where installation=j.installation and perfil_id=j.recipient;
  else
    update android_push_private.outbox set sent_at=case when p_success then now() else null end,
      last_error=case when p_success then null else left(p_error,300) end,
      leased_until=null,lease_id=null,
      next_attempt=now()+make_interval(secs=>least(3600,30*power(2,attempts)::integer))
    where id=p_job;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_notification_push(p_job uuid, p_lease uuid, p_success boolean, p_error text, p_invalid boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j notification_private.outbox%rowtype;
begin
  select * into j from notification_private.outbox where id = p_job and lease_id = p_lease for update;
  if not found then return; end if;
  if p_invalid then
    delete from notification_private.devices where installation = j.installation and perfil_id = j.recipient;
  else
    update notification_private.outbox set sent_at = case when p_success then now() else null end,
      last_error = left(p_error,300),leased_until = null,
      next_attempt = now() + make_interval(secs => least(3600,30 * power(2,attempts)::integer))
    where id = p_job;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION moderation_private.validate_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare content text;
begin
  content:=lower(regexp_replace(coalesce(to_jsonb(new)->>'contenido',
    (to_jsonb(new)->>'asunto')||' '||(to_jsonb(new)->>'mensaje'),''),'[[:space:][:punct:]]+',' ','g'));
  if exists(select 1 from moderation_private.blocked_phrases p
    where position(' '||p.phrase||' ' in ' '||content||' ')>0) then
    raise exception 'El contenido contiene expresiones no permitidas. Revísalo antes de publicarlo.' using errcode='22023';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.my_account_access()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare state text;
begin
  if auth.uid() is null then raise exception 'Sesion requerida' using errcode = '42501'; end if;
  select estado into state from account_private.access where user_id = auth.uid();
  if state is null then raise exception 'No existe el perfil de acceso. Contacta con administracion.' using errcode = '42501'; end if;
  return jsonb_build_object('estado',state);
end;
$function$

CREATE OR REPLACE FUNCTION notification_private.bulletin_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.comunicados%rowtype; recipient uuid; kind text; title text; body text;
begin
  if tg_op = 'UPDATE' and (old.asunto,old.mensaje) is not distinct from (new.asunto,new.mensaje) then return new; end if;
  if tg_op = 'DELETE' then c := old; else c := new; end if;
  kind := case tg_op when 'INSERT' then 'comunicado_nuevo' when 'UPDATE' then 'comunicado_actualizado' else 'comunicado_eliminado' end;
  title := case tg_op when 'INSERT' then 'Nuevo Comunicado de Admin' when 'UPDATE' then 'Comunicado actualizado' else 'Comunicado retirado' end;
  body := case tg_op when 'INSERT' then c.asunto when 'UPDATE' then 'El comunicado ' || c.asunto || ' ha sido modificado'
    else 'El comunicado ' || c.asunto || ' ya no está disponible' end;
  for recipient in select id from public.perfiles loop
    perform notification_private.emit(recipient,kind,title,body,'comunicado',c.id,null,
      txid_current()::text || ':comunicado:' || c.id::text || ':' || tg_op);
  end loop;
  if tg_op = 'DELETE' then return old; end if; return new;
end;
$function$

CREATE OR REPLACE FUNCTION notification_private.cancel_stale_milestone_reminders()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare aid uuid;
begin
  if tg_table_name='asignaciones' then
    aid:=old.id;
  elsif tg_table_name='hitos_itinerario' then
    aid:=old.asignacion_id;
  else
    select asignacion_id into aid from public.hitos_itinerario where id=old.hito_id;
  end if;
  delete from public.notificaciones_app n
    where n.tipo='recordatorio' and n.destino_tipo='asignacion'
      and n.destino_id=aid
      and not notification_private.reminder_is_actionable(n.destino_id,n.perfil_id,n.payload);
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION notification_private.capture_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  aid uuid; title text; state text; team uuid[]; priority text;
  content boolean := false; progress boolean := false; milestones text[] := '{}';
begin
  if tg_op = 'UPDATE' and to_jsonb(old) = to_jsonb(new) then return new; end if;
  if tg_table_name = 'asignaciones' then
    aid := case when tg_op = 'DELETE' then old.id else new.id end;
    title := case when tg_op = 'INSERT' then new.titulo else old.titulo end;
    state := case when tg_op = 'INSERT' then null else old.estado end;
    priority := case when tg_op = 'INSERT' then null else old.nivel_prioridad end;
    content := tg_op <> 'UPDATE' or
      (to_jsonb(old) - 'estado') is distinct from (to_jsonb(new) - 'estado');
    progress := tg_op = 'UPDATE' and old.estado is distinct from new.estado;
  else
    aid := case when tg_op = 'DELETE' then old.asignacion_id else new.asignacion_id end;
    select titulo,estado,nivel_prioridad into title,state,priority from public.asignaciones where id = aid;
    if tg_table_name = 'hitos_itinerario' then
      progress := tg_op = 'UPDATE' and
        (old.completado,old.estado_hito,old.notas_incidencias) is distinct from
        (new.completado,new.estado_hito,new.notas_incidencias);
      if tg_op = 'UPDATE' and (coalesce(new.completado,false) or new.estado_hito = 'completado')
        and not (coalesce(old.completado,false) or coalesce(old.estado_hito,'') = 'completado') then
        milestones := array[coalesce(nullif(new.descripcion,''),'el hito')];
      end if;
      content := tg_op <> 'UPDATE' or
        (old.descripcion,old.fecha_programada,old.orden) is distinct from
        (new.descripcion,new.fecha_programada,new.orden);
    end if;
  end if;
  select coalesce(array_agg(distinct perfil_id),'{}') into team
    from public.asignacion_equipo where asignacion_id = aid;
  insert into notification_private.assignment_events(
    transaction_id,assignment_id,old_team,old_title,old_state,actor,content_changed,
    progress_changed,old_priority,completed_milestones)
  values(txid_current(),aid,team,title,state,auth.uid(),content,progress,priority,milestones)
  on conflict(transaction_id,assignment_id) do update set
    content_changed = assignment_events.content_changed or excluded.content_changed,
    progress_changed = assignment_events.progress_changed or excluded.progress_changed,
    completed_milestones = assignment_events.completed_milestones || excluded.completed_milestones;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION notification_private.flush_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  e notification_private.assignment_events%rowtype;
  a public.asignaciones%rowtype;
  team uuid[]; recipient uuid; kind text; title text; body text;
  event_key text; assignment_title text;
begin
  delete from notification_private.assignment_events
    where transaction_id=new.transaction_id and assignment_id=new.assignment_id returning * into e;
  if not found then return null; end if;
  if current_setting('soundisco.individual_checkin',true)='true' then return null; end if;
  select * into a from public.asignaciones where id=e.assignment_id;
  select coalesce(array_agg(distinct perfil_id),'{}') into team
    from public.asignacion_equipo where asignacion_id=e.assignment_id;
  assignment_title:=coalesce(nullif(a.titulo,''),nullif(e.old_title,''),'la actividad');
  event_key:=e.transaction_id::text||':'||e.assignment_id::text;
  for recipient in select distinct unnest(e.old_team||team) loop
    kind:=null;
    if a.id is null then
      kind:='asignacion_eliminada'; title:='Asignación cancelada';
      body:='La asignación '||assignment_title||' ha sido eliminada';
    elsif recipient=any(e.old_team) and not recipient=any(team) then
      kind:='asignacion_retirada'; title:='Asignación cancelada';
      body:='Has sido removido de la asignación '||assignment_title;
    elsif recipient=any(team) and not recipient=any(e.old_team) then
      kind:='asignacion_nueva'; title:='Nueva asignación';
      body:=case when a.tipo_flujo='campo' then 'Se te ha asignado al montaje: '
        else 'Se te ha asignado la tarea: ' end||assignment_title;
    elsif e.content_changed or
      (select array_agg(x order by x) from unnest(e.old_team) x) is distinct from
      (select array_agg(x order by x) from unnest(team) x) then
      kind:='asignacion_actualizada'; title:='Cambios en tu evento';
      body:='La asignación '||assignment_title||' ha sido modificada';
    end if;
    if kind is not null then
      perform notification_private.emit(recipient,kind,title,body,'asignacion',e.assignment_id,a.estado,event_key);
    end if;
    if a.id is not null and recipient=any(team) and lower(a.nivel_prioridad)='alta'
      and lower(coalesce(e.old_priority,''))<>'alta' then
      perform notification_private.emit(recipient,'asignacion_urgente','¡URGENTE!',
        'La asignación '||assignment_title||' ha sido marcada como urgente. Se requiere atención inmediata en el evento.',
        'asignacion',e.assignment_id,a.estado,event_key||':urgente');
    end if;
  end loop;
  return null;
end;
$function$

