CREATE OR REPLACE FUNCTION scheduling_private.assignment_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_id uuid; new_id uuid;
begin
  if tg_table_name = 'asignaciones' then
    if tg_op <> 'INSERT' then old_id := old.id; end if;
    if tg_op <> 'DELETE' then new_id := new.id; end if;
  else
    if tg_op <> 'INSERT' then old_id := old.asignacion_id; end if;
    if tg_op <> 'DELETE' then new_id := new.asignacion_id; end if;
  end if;
  if old_id is not null and old_id is distinct from new_id then
    perform scheduling_private.sync_assignment(old_id);
  end if;
  if new_id is not null then perform scheduling_private.sync_assignment(new_id); end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION scheduling_private.sync_assignment(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.asignaciones%rowtype;
begin
  select * into a from public.asignaciones where id=p_id for update;
  delete from scheduling_private.bookings where asignacion_id=p_id;
  if a.id is null or a.estado='completada' then return; end if;
  insert into scheduling_private.bookings(asignacion_id,perfil_id,periodo)
  select p_id,usuario_id,tstzrange(case when a.tipo_flujo='administrativa' then a.fecha_creacion
    else min(fecha_programada) end,max(fecha_programada),'[]')
  from (
    select c.usuario_id,h.fecha_programada from public.hitos_colaboradores c
      join public.hitos_itinerario h on h.id=c.hito_id where h.asignacion_id=p_id
    union all
    select s.usuario_id,h.fecha_programada from public.asignacion_supervisores s
      join public.hitos_itinerario h on h.asignacion_id=s.asignacion_id where s.asignacion_id=p_id
  ) members group by usuario_id order by usuario_id;
exception when exclusion_violation then
  raise exception 'Un colaborador no esta disponible entre sus hitos asignados. Revisa la seleccion.' using errcode='23P01';
end $function$

CREATE OR REPLACE FUNCTION public.undo_milestone_confirmation(p_hito_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h public.hitos_itinerario%rowtype; aid uuid; confirmation_id uuid; recipient uuid; actor_name text;
begin
  if auth.uid() is null or not coalesce(public.account_is_approved(),false) then
    raise exception 'Acceso no aprobado' using errcode='42501'; end if;
  select asignacion_id into aid from public.hitos_itinerario where id=p_hito_id;
  perform 1 from public.asignaciones where id=aid for update;
  select * into h from public.hitos_itinerario where id=p_hito_id;
  if not found then raise exception 'El hito ya no existe'; end if;
  if not exists(select 1 from public.hitos_colaboradores where hito_id=h.id and usuario_id=auth.uid()) then
    raise exception 'No estás asignado a este hito' using errcode='42501'; end if;
  if not exists(select 1 from public.hitos_colaboradores where hito_id=h.id and usuario_id=auth.uid() and confirmado_at is not null) then return; end if;
  delete from public.confirmaciones_hitos where hito_id=h.id and usuario_id=auth.uid() returning id into confirmation_id;
  update public.hitos_colaboradores set confirmado_at=null,estado='sin_confirmar',hora_programada=h.fecha_programada
    where hito_id=h.id and usuario_id=auth.uid();
  perform sla_private.advance(aid);
  select coalesce(nombre_completo,'Un colaborador') into actor_name from public.perfiles where id=auth.uid();
  for recipient in
    select id from public.perfiles where rol='admin'
    union select usuario_id from public.asignacion_supervisores where asignacion_id=aid
  loop
    perform notification_private.emit(recipient,'hito_revertido','Confirmación deshecha',
      actor_name||' deshizo su confirmación de '||h.descripcion,'asignacion',aid,null,
      'undo:'||coalesce(confirmation_id,gen_random_uuid())::text);
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.update_my_profile(p_username text, p_phone text, p_job text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_username text := btrim(coalesce(p_username, ''));
  v_phone text := btrim(coalesce(p_phone, ''));
  v_job text := btrim(coalesce(p_job, ''));
begin
  if v_user is null or not coalesce(public.account_is_approved(), false) then
    raise exception 'Tu cuenta no tiene acceso' using errcode = '42501';
  end if;
  if char_length(v_username) not between 3 and 30 or v_username !~ '^[A-Za-z0-9][A-Za-z0-9._-]*$' then
    raise exception 'El nombre de usuario no es válido' using errcode = '22023';
  end if;
  if v_phone !~ '^[0-9+() -]+$'
     or char_length(regexp_replace(v_phone, '[^0-9]', '', 'g')) not between 10 and 15 then
    raise exception 'El teléfono no es válido' using errcode = '22023';
  end if;
  if not exists(select 1 from public.cargos_empresa where nombre = v_job and activo) then
    raise exception 'Selecciona un cargo válido' using errcode = '22023';
  end if;
  update public.perfiles set nombre_usuario = v_username, telefono = v_phone, cargo = v_job
  where id = v_user;
  if not found then
    raise exception 'No se encontró tu perfil' using errcode = 'P0002';
  end if;
  update auth.users
  set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) ||
      jsonb_build_object('nombre_usuario', v_username, 'telefono', v_phone, 'cargo', v_job)
  where id = v_user;
end;
$function$

CREATE OR REPLACE FUNCTION milestone_private.create_legacy(p_asignacion jsonb, p_empleados uuid[], p_hitos jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_assignment_id uuid := coalesce(
    nullif(p_asignacion ->> 'id', '')::uuid,
    gen_random_uuid()
  );
  v_tipo text := nullif(btrim(p_asignacion ->> 'tipo_flujo'), '');
  v_titulo text := nullif(btrim(p_asignacion ->> 'titulo'), '');
  v_ubicacion text := nullif(btrim(p_asignacion ->> 'ubicacion'), '');
  v_prioridad text := nullif(btrim(p_asignacion ->> 'nivel_prioridad'), '');
  v_fecha_creacion timestamptz := coalesce(
    nullif(p_asignacion ->> 'fecha_creacion', '')::timestamptz,
    now()
  );
  v_fecha_limite timestamptz;
  v_hito_count integer;
  v_hito jsonb;
begin
  if auth.uid() is null or not coalesce(public.es_admin(), false) then
    raise exception 'Solo los administradores pueden crear asignaciones.';
  end if;

  if v_titulo is null then
    raise exception 'El titulo de la asignacion es obligatorio.';
  end if;

  if v_tipo not in ('campo', 'administrativa') then
    raise exception 'El tipo de flujo no es valido.';
  end if;

  if v_prioridad not in ('baja', 'media', 'alta') then
    raise exception 'El nivel de prioridad no es valido.';
  end if;

  if coalesce(cardinality(p_empleados), 0) = 0 then
    raise exception 'Selecciona al menos un responsable.';
  end if;

  if jsonb_typeof(coalesce(p_hitos, '[]'::jsonb)) <> 'array' then
    raise exception 'Los hitos deben enviarse como un arreglo.';
  end if;

  v_hito_count := jsonb_array_length(coalesce(p_hitos, '[]'::jsonb));

  if v_tipo = 'campo' then
    if v_ubicacion is null then
      raise exception 'Las operaciones de campo requieren ubicacion.';
    end if;

    if v_hito_count = 0 then
      raise exception 'Las operaciones de campo requieren al menos un hito.';
    end if;
  else
    if v_ubicacion is not null then
      raise exception 'Las tareas administrativas no deben incluir ubicacion.';
    end if;

  end if;

  if v_hito_count = 0 then
    raise exception 'La asignacion requiere al menos un hito.';
  end if;

    for v_hito in select value from jsonb_array_elements(p_hitos)
    loop
      if nullif(v_hito ->> 'id', '') is null
        or nullif(btrim(v_hito ->> 'descripcion'), '') is null
        or nullif(v_hito ->> 'orden', '') is null
        or nullif(v_hito ->> 'fecha_programada', '') is null
        or nullif(v_hito ->> 'hora_estimada', '') is null then
        raise exception 'Cada hito requiere id, titulo, orden, fecha y hora.';
      end if;
    end loop;

    if (
      select count(distinct value ->> 'id')
      from jsonb_array_elements(p_hitos)
    ) <> v_hito_count then
      raise exception 'Los identificadores de los hitos no pueden repetirse.';
    end if;

    if (
      select count(distinct (value ->> 'orden')::integer)
      from jsonb_array_elements(p_hitos)
    ) <> v_hito_count then
      raise exception 'El orden de los hitos no puede repetirse.';
    end if;

  if exists (
    select 1 from (
      select (h ->> 'fecha_programada')::timestamptz as fecha,
        lag((h ->> 'fecha_programada')::timestamptz)
          over (order by (h ->> 'orden')::integer) as anterior
      from jsonb_array_elements(p_hitos) h
    ) ordered_hitos
    where fecha < anterior
  ) then
    raise exception 'Las fechas de los hitos deben seguir el orden del itinerario.';
  end if;

  if v_tipo = 'administrativa' and exists (
    select 1 from jsonb_array_elements(p_hitos) h
    where (h ->> 'fecha_programada')::timestamptz
      < v_fecha_creacion
  ) then
    raise exception 'Los hitos administrativos no pueden ser anteriores a la creacion.';
  end if;

  if v_tipo = 'administrativa' then
    select (h ->> 'fecha_programada')::timestamptz
      into v_fecha_limite
    from jsonb_array_elements(p_hitos) h
    order by (h ->> 'orden')::integer desc
    limit 1;
  end if;

  insert into public.asignaciones (
    id,
    titulo,
    tipo_flujo,
    ubicacion,
    nivel_prioridad,
    instrucciones,
    estado,
    fecha_creacion,
    fecha_limite
  ) values (
    v_assignment_id,
    v_titulo,
    v_tipo,
    case when v_tipo = 'campo' then v_ubicacion else null end,
    v_prioridad,
    nullif(btrim(p_asignacion ->> 'instrucciones'), ''),
    coalesce(nullif(p_asignacion ->> 'estado', ''), 'pendiente'),
    v_fecha_creacion,
    case when v_tipo = 'administrativa' then v_fecha_limite else null end
  );

  insert into public.asignacion_equipo (asignacion_id, perfil_id)
  select v_assignment_id, perfil_id
  from unnest(p_empleados) as perfil_id
  group by perfil_id;

    insert into public.hitos_itinerario (
      id,
      asignacion_id,
      orden,
      descripcion,
      hora_estimada,
      completado,
      estado_hito,
      fecha_programada
    )
    select
      (hito ->> 'id')::uuid,
      v_assignment_id,
      (hito ->> 'orden')::integer,
      btrim(hito ->> 'descripcion'),
      (hito ->> 'hora_estimada')::time,
      false,
      case
        when (hito ->> 'orden')::integer = 1 then 'en_curso'
        else 'bloqueado'
      end,
      (hito ->> 'fecha_programada')::timestamptz
    from jsonb_array_elements(p_hitos) as hito;

  return v_assignment_id;
end;
$function$

CREATE OR REPLACE FUNCTION milestone_private.update_legacy(p_asignacion_id uuid, p_asignacion jsonb, p_empleados uuid[], p_hitos jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.asignaciones%rowtype;
  v_hito jsonb;
  v_progress boolean;
  v_count integer;
begin
  if auth.uid() is null or not coalesce(public.es_admin(), false) then
    raise exception 'Solo administradores pueden editar asignaciones' using errcode = '42501';
  end if;

  select * into v_old
  from public.asignaciones
  where id = p_asignacion_id
  for update;
  if not found then
    raise exception 'La asignacion ya no existe' using errcode = 'P0002';
  end if;

  perform 1
  from public.hitos_itinerario
  where asignacion_id = p_asignacion_id
  order by orden
  for update;

  if nullif(btrim(p_asignacion->>'titulo'), '') is null
     or coalesce(cardinality(p_empleados), 0) = 0
     or coalesce(p_asignacion->>'nivel_prioridad', '') not in ('baja', 'media', 'alta') then
    raise exception 'Revisa titulo, responsables y prioridad' using errcode = '23514';
  end if;
  if (p_asignacion->>'tipo_flujo') is distinct from v_old.tipo_flujo then
    raise exception 'No se puede cambiar el tipo de una asignacion existente' using errcode = '23514';
  end if;
  if jsonb_typeof(p_hitos) is distinct from 'array' then
    raise exception 'Itinerario invalido' using errcode = '23514';
  end if;

  v_count := jsonb_array_length(p_hitos);
  if v_count = 0 then
    raise exception 'La asignacion requiere al menos un hito' using errcode = '23514';
  end if;

  if v_old.tipo_flujo = 'campo' then
    if nullif(btrim(p_asignacion->>'ubicacion'), '') is null then
      raise exception 'Campo requiere ubicacion e itinerario' using errcode = '23514';
    end if;
  elsif nullif(p_asignacion->>'ubicacion', '') is not null then
    raise exception 'Administracion no admite ubicacion' using errcode = '23514';
  end if;

  if exists (
    select 1 from jsonb_array_elements(p_hitos) h
    where nullif(btrim(h->>'descripcion'), '') is null
      or nullif(h->>'fecha_programada', '') is null
      or nullif(h->>'id', '') is null
      or coalesce((h->>'orden')::integer, 0) < 1
  ) then
    raise exception 'Cada hito requiere titulo, fecha y orden' using errcode = '23514';
  end if;
  if (select count(distinct h->>'id') from jsonb_array_elements(p_hitos) h) <> v_count
    or (select count(distinct h->>'orden') from jsonb_array_elements(p_hitos) h) <> v_count then
    raise exception 'Los hitos deben tener IDs y ordenes unicos' using errcode = '23514';
  end if;
  if exists (
    select 1 from (
      select (h->>'fecha_programada')::timestamptz fecha,
        lag((h->>'fecha_programada')::timestamptz)
          over (order by (h->>'orden')::integer) anterior
      from jsonb_array_elements(p_hitos) h
    ) ordered_hitos
    where fecha < anterior
  ) then
    raise exception 'Las fechas de los hitos deben seguir el orden del itinerario' using errcode = '23514';
  end if;
  if v_old.tipo_flujo = 'administrativa' and exists (
    select 1 from jsonb_array_elements(p_hitos) h
    where (h->>'fecha_programada')::timestamptz < v_old.fecha_creacion
  ) then
    raise exception 'Los hitos administrativos no pueden ser anteriores a la creacion' using errcode = '23514';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_hitos) j
    join public.hitos_itinerario h on h.id = (j->>'id')::uuid
    where h.asignacion_id <> p_asignacion_id
  ) then
    raise exception 'Hito ajeno a la asignacion' using errcode = '42501';
  end if;

  select exists (
    select 1 from public.hitos_itinerario
    where asignacion_id = p_asignacion_id
      and (coalesce(completado, false) or estado_hito = 'completado')
  ) into v_progress;

  if v_progress and exists (
    select 1 from public.hitos_itinerario h
    where h.asignacion_id = p_asignacion_id
      and (coalesce(h.completado, false) or h.estado_hito = 'completado')
      and not exists (
        select 1 from jsonb_array_elements(p_hitos) j
        where (j->>'id')::uuid = h.id and (j->>'orden')::integer = h.orden
      )
  ) then
    raise exception 'Los hitos completados deben conservarse en su posicion original' using errcode = '23514';
  end if;

  update public.asignaciones
  set titulo = btrim(p_asignacion->>'titulo'),
    ubicacion = nullif(btrim(p_asignacion->>'ubicacion'), ''),
    nivel_prioridad = p_asignacion->>'nivel_prioridad',
    instrucciones = nullif(btrim(p_asignacion->>'instrucciones'), ''),
    fecha_limite = case when v_old.tipo_flujo = 'administrativa' then (
      select (h->>'fecha_programada')::timestamptz
      from jsonb_array_elements(p_hitos) h
      order by (h->>'orden')::integer desc
      limit 1
    ) else null end
  where id = p_asignacion_id;

  delete from public.asignacion_equipo
  where asignacion_id = p_asignacion_id;
  insert into public.asignacion_equipo(asignacion_id, perfil_id)
    select p_asignacion_id, e
    from (select distinct unnest(p_empleados) e) s;

  delete from public.hitos_itinerario h
  where asignacion_id = p_asignacion_id
    and not exists (
      select 1 from jsonb_array_elements(p_hitos) j
      where (j->>'id')::uuid = h.id
    );

  for v_hito in select value from jsonb_array_elements(p_hitos) loop
    insert into public.hitos_itinerario(
      id, asignacion_id, orden, descripcion, hora_estimada,
      fecha_programada, estado_hito, completado
    ) values (
      (v_hito->>'id')::uuid, p_asignacion_id, (v_hito->>'orden')::integer,
      btrim(v_hito->>'descripcion'), (v_hito->>'hora_estimada')::time,
      (v_hito->>'fecha_programada')::timestamptz, 'bloqueado', false
    )
    on conflict(id) do update
    set orden = excluded.orden,
      descripcion = excluded.descripcion,
      hora_estimada = excluded.hora_estimada,
      fecha_programada = excluded.fecha_programada;
  end loop;

  update public.hitos_itinerario
  set estado_hito = 'bloqueado'
  where asignacion_id = p_asignacion_id
    and not (coalesce(completado, false) or estado_hito = 'completado');
  update public.hitos_itinerario
  set estado_hito = 'en_curso'
  where id = (
    select id from public.hitos_itinerario
    where asignacion_id = p_asignacion_id
      and not (coalesce(completado, false) or estado_hito = 'completado')
    order by orden
    limit 1
  );

  update public.asignaciones
  set estado = case
    when not exists (
      select 1 from public.hitos_itinerario h
      where h.asignacion_id = p_asignacion_id
        and not (coalesce(h.completado, false) or h.estado_hito = 'completado')
    ) then 'completada'
    when exists (
      select 1 from public.hitos_itinerario h
      where h.asignacion_id = p_asignacion_id
        and (coalesce(h.completado, false) or h.estado_hito = 'completado')
    ) then 'en_curso'
    else 'pendiente'
  end
  where id = p_asignacion_id;
end;
$function$

CREATE OR REPLACE FUNCTION milestone_private.validate_members(p_hitos jsonb, p_supervisores jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j jsonb; members uuid[]; supervisors uuid[];
begin
  if auth.uid() is null or not public.account_is_approved() or not public.es_admin() then
    raise exception 'Solo administradores pueden gestionar hitos' using errcode='42501'; end if;
  if jsonb_typeof(p_hitos) is distinct from 'array' or jsonb_array_length(p_hitos)=0 then
    raise exception 'Agrega al menos un hito'; end if;
  for j in select value from jsonb_array_elements(p_hitos) loop
    if jsonb_typeof(j->'colaboradores') is distinct from 'array' then
      raise exception 'Actualiza la app: selecciona colaboradores en cada hito'; end if;
    if jsonb_array_length(j->'colaboradores')=0 then raise exception 'Cada hito necesita colaboradores'; end if;
  end loop;
  if jsonb_typeof(p_supervisores) is distinct from 'array' then raise exception 'Supervisores invalidos'; end if;
  select coalesce(array_agg(distinct u.value::uuid),'{}') into members
    from jsonb_array_elements(p_hitos) h cross join lateral jsonb_array_elements_text(h->'colaboradores') u;
  select coalesce(array_agg(distinct value::uuid),'{}') into supervisors from jsonb_array_elements_text(p_supervisores);
  if exists(select 1 from unnest(members||supervisors) u where not exists(
    select 1 from public.perfiles p join account_private.access a on a.user_id=p.id
    where p.id=u and a.estado='aprobada')) then
    raise exception 'Selecciona usuarios con acceso aprobado'; end if;
  return array(select distinct unnest(members||supervisors));
end $function$

CREATE OR REPLACE FUNCTION sla_private.advance_from_check_in()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare assignment_id uuid;
begin
  select h.asignacion_id into assignment_id
  from public.hitos_itinerario h where h.id = new.hito_id;
  if assignment_id is not null then perform sla_private.advance(assignment_id); end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION sla_private.protect_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists(select 1 from public.confirmaciones_hitos where hito_id=old.id) then
    if tg_op='DELETE' then
      if exists(select 1 from public.asignaciones where id=old.asignacion_id)
        and not (coalesce(current_setting('soundisco.deleting_assignment',true),'')=old.asignacion_id::text
          and public.es_admin()) then
        raise exception 'No puedes eliminar un hito con confirmaciones'; end if;
      return old;
    end if;
    if (new.asignacion_id,new.orden,new.fecha_programada) is distinct from (old.asignacion_id,old.orden,old.fecha_programada) then
      raise exception 'No puedes cambiar el horario ni orden de un hito confirmado'; end if;
  end if;
  return new;
end $function$
